4294916144,4294967295,4294967295,4294967295},'{4294916401,4294967295,4294967295,4294967295},'{4294916658,4294967295,4294967295,4294967295},'{4294916915,4294967295,4294967295,4294967295},'{4294917172,4294967295,4294967295,4294967295},'{4294917429,4294967295,4294967295,4294967295},'{4294917686,4294967295,4294967295,4294967295},'{4294917943,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295}},'{'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295},'{4294967295,4294967295,4294967295,4294967295}}};

    localparam int MODE_WIDTH = 4;

    logic                    clk_i;
    logic                    rst_ni;
    logic [   PE_WIDTH-1:0]  pe_in_a;
    logic [   PE_WIDTH-1:0]  pe_in_b;
    logic [ MODE_WIDTH-1:0]  mode;

    localparam int NUM_LANE = 8;
    localparam int ACC_W    = 20;
    logic [ACC_W-1:0] acc_word [0:NUM_LANE-1];
    logic             sel_acc;
    logic [ACC_W-1:0] pe_out   [0:NUM_LANE-1];

    logic signed [15:0] A_re [0:MAXM-1][0:MAXK-1];
    logic signed [15:0] A_im [0:MAXM-1][0:MAXK-1];
    logic signed [15:0] B_re [0:MAXK-1][0:MAXN-1];
    logic signed [15:0] B_im [0:MAXK-1][0:MAXN-1];
    longint             X_re [0:MAXO-1];
    longint             X_im [0:MAXO-1];

    int err;
    int npass;

    top_pe_bas top_pe_bas_i (
        .clk_i    (clk_i),
        .rst_ni   (rst_ni),
        .pe_in_a_i(pe_in_a),
        .pe_in_b_i(pe_in_b),
        .mode_i   (mode),
        .sel_acc_i(sel_acc),
        .acc_i    (acc_word),
        .pe_out_o (pe_out)
    );

    initial clk_i = 1'b0;
    always #5 clk_i = ~clk_i;

    function automatic logic signed [15:0] rand_signed(input int width);
        logic [15:0] r;
        int pk;
        r = 16'($urandom);
        pk = $urandom % 5;
        case (width)
            4:       return (pk == 0) ? -16'sd8     : (pk == 1) ? 16'sd7     : 16'($signed(r[3:0]));
            8:       return (pk == 0) ? -16'sd128   : (pk == 1) ? 16'sd127   : 16'($signed(r[7:0]));
            default: return (pk == 0) ? -16'sd32768 : (pk == 1) ? 16'sd32767 : $signed(r);
        endcase
    endfunction

    function automatic logic signed [15:0] rand_signed_sym(input int width);
        int m;
        m = (1 << (width - 1)) - 1;
        return 16'($signed(($urandom % (2*m + 1)) - m));
    endfunction

    function automatic longint read_result(input int lvl, input int node);
        int hlane, llane;
        if (lvl == 0) return longint'($signed(pe_out[node]));
        case (lvl)
            1:       begin hlane = 2*node;        llane = 2*node + 1;    end
            2:       begin hlane = (node==0)?2:6; llane = (node==0)?3:7; end
            default: begin hlane = 6;             llane = 7;             end
        endcase
        return longint'($signed({pe_out[hlane], pe_out[llane]}));
    endfunction

    task automatic rand_matrices(input int mi);
        int M, K, N, PA, PB, cplx;
        M = MM_DIMS[mi][0]; K = MM_DIMS[mi][1]; N = MM_DIMS[mi][2];
        PA = MM_DIMS[mi][3]; PB = MM_DIMS[mi][4]; cplx = MM_DIMS[mi][5];
        for (int m = 0; m < M; m++)
            for (int k = 0; k < K; k++) begin
                A_re[m][k] = rand_signed(PA);
                A_im[m][k] = (cplx != 0) ? rand_signed(PA) : 16'sd0;
            end
        for (int k = 0; k < K; k++)
            for (int n = 0; n < N; n++) begin
                B_re[k][n] = rand_signed(PB);
                B_im[k][n] = (cplx != 0) ? rand_signed_sym(PB) : 16'sd0;
            end
    endtask

    task automatic golden(input int mi);
        int K, NOUT, m, n;
        longint re, im;
        K = MM_DIMS[mi][1]; NOUT = MM_DIMS[mi][6];
        for (int o = 0; o < NOUT; o++) begin
            m = MM_OUT[mi][o][0]; n = MM_OUT[mi][o][1];
            re = 0; im = 0;
            for (int k = 0; k < K; k++) begin
                re = re + longint'(A_re[m][k]) * longint'(B_re[k][n])
                        - longint'(A_im[m][k]) * longint'(B_im[k][n]);
                im = im + longint'(A_re[m][k]) * longint'(B_im[k][n])
                        + longint'(A_im[m][k]) * longint'(B_re[k][n]);
            end
            X_re[o] = re;
            X_im[o] = im;
        end
    endtask

    task automatic pack(input int mi);
        int M, K, N, PA, cplx, pos;
        pe_in_a = '0;
        pe_in_b = '0;
        M = MM_DIMS[mi][0]; K = MM_DIMS[mi][1]; N = MM_DIMS[mi][2];
        PA = MM_DIMS[mi][3]; cplx = MM_DIMS[mi][5];
        for (int m = 0; m < M; m++)
            for (int k = 0; k < K; k++) begin
                pos = MM_RE_A[mi][m][k] & 255;
                if (pos != 255) pe_in_a[pos*8 +: 8] = A_re[m][k][7:0];
                if (PA == 16) begin
                    pos = (MM_RE_A[mi][m][k] >> 8) & 255;
                    if (pos != 255) pe_in_a[pos*8 +: 8] = A_re[m][k][15:8];
                end
                if (cplx != 0) begin
                    pos = MM_IM_A[mi][m][k] & 255;
                    if (pos != 255) pe_in_a[pos*8 +: 8] = A_im[m][k][7:0];
                    if (PA == 16) begin
                        pos = (MM_IM_A[mi][m][k] >> 8) & 255;
                        if (pos != 255) pe_in_a[pos*8 +: 8] = A_im[m][k][15:8];
                    end
                end
            end
        if (MODE_NUM[mi] == 12)
            pack_b_c16c16();
        else
            for (int k = 0; k < K; k++)
                for (int n = 0; n < N; n++)
                    for (int p = 0; p < 4; p++) begin
                        pos = (MM_RE_B[mi][k][n] >> (8*p)) & 255;
                        if (pos != 255) pe_in_b[pos*4 +: 4] = B_re[k][n][p*4 +: 4];
                        if (cplx != 0) begin
                            pos = (MM_IM_B[mi][k][n] >> (8*p)) & 255;
                            if (pos != 255) pe_in_b[pos*4 +: 4] = B_im[k][n][p*4 +: 4];
                        end
                    end
    endtask

    task automatic put_b16(input logic [15:0] v, input int blk_hi, input int blk_lo, input int lane);
        pe_in_b[(blk_hi*16 + 8 + lane)*4 +: 4] = v[15:12];
        pe_in_b[(blk_hi*16     + lane)*4 +: 4] = v[11:8];
        pe_in_b[(blk_lo*16 + 8 + lane)*4 +: 4] = v[7:4];
        pe_in_b[(blk_lo*16     + lane)*4 +: 4] = v[3:0];
    endtask

    task automatic pack_b_c16c16;
        for (int k = 0; k < 4; k++) begin
            put_b16( B_re[k][0], 0, 1, k);
            put_b16(-B_im[k][0], 0, 1, 4 + k);
            put_b16( B_im[k][0], 2, 3, k);
            put_b16( B_re[k][0], 2, 3, 4 + k);
        end
    endtask

    task automatic compare(input int mi);
        int NOUT, lvl, rn, in;
        longint r;
        NOUT = MM_DIMS[mi][6]; lvl = TAP_LEVEL[mi];
        for (int o = 0; o < NOUT; o++) begin
            rn = MM_OUT[mi][o][2];
            in = MM_OUT[mi][o][3];
            r = read_result(lvl, rn);
            if (r !== X_re[o]) begin
                err = err + 1;
                $display("mode %0d output %0d Re: golden=%0d dut=%0d", MODE_NUM[mi], o, X_re[o], r);
            end
            if (in >= 0) begin
                r = read_result(lvl, in);
                if (r !== X_im[o]) begin
                    err = err + 1;
                    $display("mode %0d output %0d Im: golden=%0d dut=%0d", MODE_NUM[mi], o, X_im[o], r);
                end
            end
        end
    endtask

    task automatic clear_acc;
        for (int j = 0; j < NUM_LANE; j++) acc_word[j] = '0;
    endtask

    task automatic set_acc(input int lvl, input int node, input longint val);
        int hlane, llane;
        if (lvl == 0) begin
            acc_word[node] = val[ACC_W-1:0];
            return;
        end
        case (lvl)
            1:       begin hlane = 2*node;        llane = 2*node + 1;   end
            2:       begin hlane = (node==0)?2:6; llane = (node==0)?3:7; end
            default: begin hlane = 6;             llane = 7;            end
        endcase
        acc_word[hlane] = val[2*ACC_W-1:ACC_W];
        acc_word[llane] = val[ACC_W-1:0];
    endtask

    longint acc_seed    [0:MAXO-1];
    longint acc_seed_im [0:MAXO-1];

    initial begin
        int err0, NOUT, lvl, rn, in;
        longint r, gexp;
        $display("\nStarting top_pe_bas verification (%0d modes x %0d random)...\n",
                 NUM_MODE, NUM_RAND);
`ifdef VCD
        $dumpfile("activity.vcd");
        $dumpvars(0, tb_top_pe_bas.top_pe_bas_i);
`endif

        rst_ni  = 1'b0;
        pe_in_a = '0;
        pe_in_b = '0;
        mode    = '0;
        sel_acc = 1'b0;
        clear_acc();
        err = 0; npass = 0;
        repeat (3) @(posedge clk_i);
        rst_ni = 1'b1;

        for (int mi = 0; mi < NUM_MODE; mi++) begin
            mode = MODE_WIDTH'(MODE_NUM[mi]);
            clear_acc();
            sel_acc = 1'b0;
            err0 = err;
            for (int t = 0; t < NUM_RAND; t++) begin
                rand_matrices(mi);
                golden(mi);
                pack(mi);
                @(posedge clk_i);
                @(posedge clk_i);
                @(posedge clk_i);
                #1;
                compare(mi);
            end
            if (err == err0) begin
                npass = npass + 1;
                $display("  mode %0d: PASS", MODE_NUM[mi]);
            end else
                $display("  mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

        $display("\nAccumulation scenario: external seed + %0d feedback iterations...", NUM_ACC);
        for (int mi = 0; mi < NUM_MODE; mi++) begin
            mode = MODE_WIDTH'(MODE_NUM[mi]);
            rand_matrices(mi);
            golden(mi);
            pack(mi);
            NOUT = MM_DIMS[mi][6];
            lvl  = TAP_LEVEL[mi];
            clear_acc();
            for (int o = 0; o < NOUT; o++) begin
                acc_seed[o] = longint'(rand_signed(16));
                set_acc(lvl, MM_OUT[mi][o][2], acc_seed[o]);
                if (MM_OUT[mi][o][3] >= 0) begin
                    acc_seed_im[o] = longint'(rand_signed(16));
                    set_acc(lvl, MM_OUT[mi][o][3], acc_seed_im[o]);
                end
            end
            sel_acc = 1'b0;
            @(posedge clk_i);
            #1;
            for (int it = 1; it < NUM_ACC; it++) begin
                sel_acc = 1'b1;
                @(posedge clk_i);
            end
            repeat (2) @(posedge clk_i);
            #1;
            err0 = err;
            for (int o = 0; o < NOUT; o++) begin
                rn = MM_OUT[mi][o][2];
                in = MM_OUT[mi][o][3];
                r    = read_result(lvl, rn);
                gexp = acc_seed[o] + NUM_ACC * X_re[o];
                if (r !== gexp) begin
                    err = err + 1;
                    $display("  acc mode %0d out %0d Re: golden=%0d dut=%0d", MODE_NUM[mi], o, gexp, r);
                end
                if (in >= 0) begin
                    r    = read_result(lvl, in);
                    gexp = acc_seed_im[o] + NUM_ACC * X_im[o];
                    if (r !== gexp) begin
                        err = err + 1;
                        $display("  acc mode %0d out %0d Im: golden=%0d dut=%0d", MODE_NUM[mi], o, gexp, r);
                    end
                end
            end
            if (err == err0)
                $display("  acc mode %0d: PASS", MODE_NUM[mi]);
            else
                $display("  acc mode %0d: FAIL (%0d mismatches)", MODE_NUM[mi], err - err0);
        end

`ifdef VCD
        $dumpoff;
`endif
        $display("\ntop_pe_bas verification: %0d/%0d single-shot modes passed (%0d total mismatches)\n",
                 npass, NUM_MODE, err);
        $finish;
    end

endmodule
